mapper.select:
SELECT 
FROM rule_execution
WHERE user_id = #{userId}

    AND rule_id = #{ruleId}


    AND device_id = #{deviceId}


    AND status = #{status}

ORDER BY created_at DESC

mapper.update:
UPDATE rule_execution
SET status = 'SUCCESS',
    finished_at = #{finishedAt,jdbcType=TIMESTAMP},
    updated_at = #{finishedAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND status = 'PENDING'

mapper.delete:
DELETE FROM rule_execution
WHERE status IN ('SUCCESS', 'FAILED')
  AND finished_at IS NOT NULL
  AND finished_at < #{before,jdbcType=TIMESTAMP}
LIMIT #{limit}
